<script setup lang="ts">
/**
 * FiLColorWizard - Cyberpunk HUD panel for automatic color correction & quick presets.
 */
import { computed } from "vue";
import { FilSection, FilComboBox, FilSlider, FilToggle, type FilComboOption } from "@/components/widgets";
import type { FilNodeState } from "@/nodes2/filState";
import { findFilWidget } from "@/nodes2/util";
import { NODE_CONTRACTS } from "@/api/contracts";
import { useI18n } from "@/composables/useI18n";
import { useWidgetSockets } from "@/composables/useWidgetSockets";
import { COLOR_WIZARD_SOCKET_INPUTS } from "@/nodes2/nodes/color_wizard";

const props = defineProps<{ state: FilNodeState }>();
const { t } = useI18n();

// `saturate` has a socket too but no field in this panel — it is graph-driven
// only, so its dot stays in the fallback row rather than tracking a field.
const { setFieldEl, isLinked } = useWidgetSockets(props.state, COLOR_WIZARD_SOCKET_INPUTS);
const linkedTip = (name: string, own: string) =>
  isLinked(name) ? t("fld_linked_tt", "Driven by the connected input — disconnect it to edit here.") : own;

// Methods come from the generated contract (backed by METHODS in
// common/color_correction.py), never from literals here: "LAB Contrast" is not a
// key METHODS knows — METHODS.get(method, METHODS["Full Auto"]) silently fell
// back to Full Auto, so picking it quietly ran a different algorithm, and the
// value is not even legal for the COMBO input.
const cwContract = NODE_CONTRACTS["FiLColorWizard"];
const methodSpec =
  cwContract?.inputs.required.find((i) => i.name === "method") ||
  cwContract?.inputs.optional.find((i) => i.name === "method");
// A dropdown, not a segmented strip: five method names never fit across a
// ~290px node — measured live, every option was clipped to 53px of the 61–95px
// it needed, so not one of them was readable. The contract declares this widget
// as `combo` for exactly that reason.
const methodOptions = computed<FilComboOption[]>(() =>
  (methodSpec?.values?.length ? methodSpec.values : ["Full Auto"]).map((value) => ({ value })),
);

function createRef<T>(name: string, defaultValue: T) {
  return computed<T>({
    get: () => (props.state.nodeState[name] as T) ?? defaultValue,
    set: (val: T) => {
      props.state.nodeState[name] = val;
      const w = props.state.node ? findFilWidget(props.state.node, name) : null;
      if (w) w.value = val;
    },
  });
}

const method = createRef<string>("method", "Full Auto");
const strength = createRef<number>("strength", 0.8);
const saturate = createRef<number>("saturate", 0.5);
const temperature = createRef<number>("temperature", 0.0);
const tint = createRef<number>("tint", 0.0);
const preserveSkin = createRef<boolean>("preserve_skin", false);

function isSlotConnected(slotName: string): boolean {
  const node = props.state.node as { inputs?: Array<{ name: string; link: number | null }> } | undefined;
  if (!node?.inputs) return false;
  const slot = node.inputs.find((s) => s.name === slotName);
  return Boolean(slot && slot.link != null);
}

const hasReference = computed(() => isSlotConnected("reference"));
const hasWBMask = computed(() => isSlotConnected("wb_mask"));

function resetAdjustments() {
  strength.value = 0.8;
  saturate.value = 0.5;
  temperature.value = 0.0;
  tint.value = 0.0;
  preserveSkin.value = false;
}

function applyPreset(preset: "warm" | "cool" | "skin" | "contrast") {
  if (preset === "warm") {
    method.value = "Full Auto";
    temperature.value = 0.35;
    tint.value = 0.0;
    strength.value = 0.8;
    preserveSkin.value = true;
  } else if (preset === "cool") {
    method.value = "Full Auto";
    temperature.value = -0.35;
    tint.value = 0.15;
    strength.value = 0.85;
    preserveSkin.value = false;
  } else if (preset === "skin") {
    method.value = "White Patch";
    temperature.value = 0.05;
    tint.value = 0.0;
    strength.value = 0.75;
    preserveSkin.value = true;
  } else if (preset === "contrast") {
    // "LAB Enhance" is the actual METHODS key; "LAB Contrast" did not exist and
    // silently fell back to Full Auto.
    method.value = "LAB Enhance";
    temperature.value = 0.0;
    tint.value = 0.0;
    strength.value = 0.9;
    preserveSkin.value = false;
  }
}

// Section collapse state lives in `state.ui`, same pattern as the other
// panels: an unbound FilSection flips its ▼ arrow on click and hides nothing.
function isCollapsed(section: string): boolean {
  return Boolean((props.state.ui as Record<string, unknown>)[`collapsed_${section}`]);
}
function setCollapsed(section: string, collapsed: boolean) {
  (props.state.ui as Record<string, unknown>)[`collapsed_${section}`] = collapsed;
}
</script>

<template>
  <div class="fil-color-wizard-root">
    <!-- Active Inputs Badges -->
    <div v-if="hasReference || hasWBMask" class="fil-cw-status-bar">
      <span v-if="hasReference" class="fil-cw-status-badge" :title="t('tt_cw_reference', 'Reference image connected')">
        🟢 {{ t('cw_connected_ref', 'Ref Image') }}
      </span>
      <span v-if="hasWBMask" class="fil-cw-status-badge" :title="t('tt_cw_wb_mask', 'WB mask connected')">
        🟢 {{ t('cw_connected_wb', 'WB Mask') }}
      </span>
    </div>

    <!-- Quick Presets -->
    <div class="fil-cw-presets-block">
      <div class="fil-cw-presets-title">{{ t('cw_presets', '⚡ Quick Presets') }}</div>
      <div class="fil-cw-presets-grid">
        <button type="button" class="fil-cw-preset-btn warm"
          :title="t('cw_preset_warm_tt', 'Warm Sunny Tone')" @click="applyPreset('warm')">
          {{ t('cw_preset_warm', '☀️ Warm Sun') }}
        </button>
        <button type="button" class="fil-cw-preset-btn cool"
          :title="t('cw_preset_cool_tt', 'Cool Sci-Fi Cyberpunk Tone')" @click="applyPreset('cool')">
          {{ t('cw_preset_cool', '🧊 Cool Sci-Fi') }}
        </button>
        <button type="button" class="fil-cw-preset-btn skin"
          :title="t('cw_preset_skin_tt', 'Natural Skin Preservation')" @click="applyPreset('skin')">
          {{ t('cw_preset_skin', '👤 Skin Protect') }}
        </button>
        <button type="button" class="fil-cw-preset-btn contrast"
          :title="t('cw_preset_contrast_tt', 'Punchy LAB Contrast')" @click="applyPreset('contrast')">
          {{ t('cw_preset_contrast', '⚡ Contrast') }}
        </button>
      </div>
    </div>

    <!-- Algorithm Method -->
    <FilSection :title="t('cw_section_method', '⚙️ Method')"
      :model-value="isCollapsed('method')" @update:model-value="(v: boolean) => setCollapsed('method', v)" />
    <FilComboBox
      v-if="!isCollapsed('method')"
      v-model="method"
      :options="methodOptions"
      :title="t('tt_cw_method', 'Correction algorithm.')"
    />

    <!-- Adjustment Sliders -->
    <div class="fil-cw-adjust-header">
      <FilSection :title="t('cw_section_adjust', '🎛️ Adjustments')"
        :model-value="isCollapsed('adjust')" @update:model-value="(v: boolean) => setCollapsed('adjust', v)" />
      <button v-if="!isCollapsed('adjust')" type="button" class="fil-cw-reset-btn" :title="t('cw_reset_tt', 'Reset sliders to default values')" @click="resetAdjustments">
        {{ t('cw_reset', '↺ Reset') }}
      </button>
    </div>

    <template v-if="!isCollapsed('adjust')">
      <div class="fil-cw-slider-group">
        <FilSlider :ref="(el: unknown) => setFieldEl('strength', el)"
          v-model="strength" :min="0" :max="1" :step="0.05" :disabled="isLinked('strength')" inline-label
          :label="t('cw_strength', 'Correction Strength')"
          :title="linkedTip('strength', t('tt_cw_strength', 'Correction strength (0 = no change).'))" />
        <FilSlider v-if="method === 'Channel Stretch'" :ref="(el: unknown) => setFieldEl('saturate', el)"
          v-model="saturate" :min="0" :max="5" :step="0.1" :disabled="isLinked('saturate')" inline-label
          :label="t('cw_saturate', 'Saturate Percentile')"
          :title="linkedTip('saturate', t('tt_cw_saturate', 'Percentile saturation for Channel Stretch.'))" />
        <FilSlider :ref="(el: unknown) => setFieldEl('temperature', el)"
          v-model="temperature" :min="-1" :max="1" :step="0.05" :disabled="isLinked('temperature')" inline-label
          :label="t('cw_temperature', 'Temperature (Warm/Cool)')"
          :title="linkedTip('temperature', t('tt_cw_temperature', 'Colour temperature.'))" />
        <FilSlider :ref="(el: unknown) => setFieldEl('tint', el)"
          v-model="tint" :min="-1" :max="1" :step="0.05" :disabled="isLinked('tint')" inline-label
          :label="t('cw_tint', 'Tint (Green/Magenta)')"
          :title="linkedTip('tint', t('tt_cw_tint', 'Colour tint.'))" />
      </div>

      <!-- Skin Protection Toggle — shared FilToggle, not a bespoke ON/OFF pill,
           so it matches the switches in UpscaleTileCalc and HiResFix. -->
      <FilToggle
        :model-value="preserveSkin ? 'ON' : 'OFF'"
        :label="t('cw_preserve_skin', '🛡️ Preserve Skin Tones')"
        :title="t('tt_cw_preserve_skin', 'Preserve skin tones.')"
        @update:model-value="(v: 'ON' | 'OFF') => (preserveSkin = v === 'ON')"
      />
    </template>
  </div>
</template>

<style scoped>
.fil-color-wizard-root {
  width: 100%; box-sizing: border-box; min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--fil-node-gap);
  padding: var(--fil-node-pad);
  color: var(--fil-text);
  font-family: ui-sans-serif, system-ui, sans-serif;
}

.fil-cw-presets-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 10px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid var(--fil-border);
  border-radius: 8px;
}
.fil-cw-presets-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--fil-accent-text);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.fil-cw-presets-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.fil-cw-preset-btn {
  height: var(--fil-control-h);
  border-radius: 6px;
  border: 1px solid var(--fil-border);
  background: var(--fil-surface-1);
  color: var(--fil-text);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.12s ease;
}
.fil-cw-preset-btn:hover {
  background: var(--fil-surface-3);
  border-color: var(--fil-accent);
}
.fil-cw-preset-btn.warm:hover {
  border-color: #ffaa00;
  color: #ffaa00;
}
.fil-cw-preset-btn.cool:hover {
  border-color: #00f0ff;
  color: #00f0ff;
}
.fil-cw-preset-btn.skin:hover {
  border-color: #ff77aa;
  color: #ff77aa;
}
.fil-cw-preset-btn.contrast:hover {
  border-color: #ffaa00;
  color: #ffaa00;
}

.fil-cw-slider-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.fil-cw-status-bar {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.fil-cw-status-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--fil-ok) 18%, transparent);
  color: var(--fil-ok);
  border: 1px solid color-mix(in srgb, var(--fil-ok) 35%, transparent);
}

.fil-cw-adjust-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  width: 100%;
}
.fil-cw-adjust-header :deep(.fil-w-section) {
  flex: 1;
}
.fil-cw-reset-btn {
  height: 24px;
  padding: 0 8px;
  border-radius: 4px;
  border: 1px solid var(--fil-border);
  background: var(--fil-surface-2);
  color: var(--fil-muted);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.12s ease;
  flex-shrink: 0;
}
.fil-cw-reset-btn:hover {
  background: var(--fil-surface-3);
  color: var(--fil-text);
  border-color: var(--fil-accent);
}

</style>
