<script setup lang="ts">
/**
 * Compact ON/OFF switch — replaces a two-button `FilSegmented(['ON','OFF'])`
 * pill for plain booleans. The row label already says what the toggle does;
 * switch position + accent color communicate state, so no per-state text.
 *
 * a11y: native <button role="switch">, Enter/Space toggle via click.
 */
import FilIcon from "./FilIcon.vue";
import type { IconName } from "@/composables/icons";

const props = defineProps<{
  label?: string;
  title?: string;
  disabled?: boolean;
  /** Compact inline mode: no label|switch grid/full-width row — sizes to
   * content so it can sit next to another field in the same row (e.g. an
   * "Auto" toggle glued onto a number input). */
  bare?: boolean;
  /** Optional glyph shown before the label — omitted by default, so
   * existing call sites are visually unchanged. */
  icon?: IconName;
}>();

const modelValue = defineModel<"ON" | "OFF">({ required: true });

function toggle() {
  if (props.disabled) return;
  modelValue.value = modelValue.value === "ON" ? "OFF" : "ON";
}
</script>

<template>
  <div class="fil-w-toggle" :class="{ bare, 'is-disabled': disabled }" :title="title">
    <label v-if="label" class="fil-w-toggle-label">
      <FilIcon v-if="icon" :name="icon" :size="12" />{{ label }}
    </label>
    <button
      type="button"
      class="fil-w-switch"
      :class="{ on: modelValue === 'ON' }"
      role="switch"
      :aria-checked="modelValue === 'ON'"
      :aria-label="label"
      :disabled="disabled"
      @click="toggle"
    >
      <span class="fil-w-switch-thumb" />
    </button>
  </div>
</template>

<style scoped>
.fil-w-toggle {
  display: grid;
  /* Deliberately NOT `--fil-label-col` (32%), which every other labelled row
   * uses so their controls line up in a column. A switch is 36px wide and is
   * pinned to the row's right edge (`justify-self: end` below), so it never
   * sat on that column boundary to begin with — reserving the other 68% for
   * it only bought dead space. Measured on a live Cleaner at 262px wide: the
   * label was clipped to 86px needing 143px, with ~94px empty beside it.
   * `auto` gives the switch exactly its own width and the label the rest;
   * nothing that was aligned before moves. */
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--fil-node-gap);
  width: 100%;
  /* The switch itself is 20px and stays that way — a control this small looks
   * wrong scaled up. The ROW still occupies a full control height so the
   * vertical rhythm of a settings stack does not stutter around it. */
  min-height: var(--fil-control-h);
}
.fil-w-toggle.is-disabled {
  opacity: 0.5;
  pointer-events: none;
}
/* …except in `bare` mode, which is an inline chip inside someone else's row
 * (see the flex override below) and must not pad that row out. */
.fil-w-toggle.bare {
  min-height: 0;
}
.fil-w-toggle-label {
  grid-column: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  color: var(--fil-muted);
  font-family: inherit;
  display: flex;
  align-items: center;
  gap: 4px;
}
.fil-w-toggle.bare {
  display: flex;
  width: auto;
  gap: 4px;
}
.fil-w-toggle.bare .fil-w-toggle-label {
  font-size: 10px;
  white-space: nowrap;
}
.fil-w-switch {
  grid-column: 2;
  /* Pinned to the right edge of the row, the way a settings row reads. With
     `start` the switch floated just past the end of the label, so short labels
     left it stranded mid-row with dead space beside it. */
  justify-self: end;
  width: 36px;
  height: 20px;
  padding: 2px;
  box-sizing: border-box;
  border: none;
  border-radius: 10px;
  background: var(--fil-surface-3);
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  outline: none;
  transition: background 0.12s;
}
.fil-w-switch.on {
  background: var(--fil-accent);
}
.fil-w-switch:disabled {
  opacity: 0.5;
  cursor: default;
}
.fil-w-switch:focus-visible {
  outline: 2px solid var(--fil-accent);
  outline-offset: 2px;
}
.fil-w-switch-thumb {
  display: block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.12s;
}
.fil-w-switch.on .fil-w-switch-thumb {
  transform: translateX(16px);
}
</style>
